return [
  {
    json: {
      success: true,
      user_id: $('Prepare Request Data').item.json.user_id || '',
      generated_at: new Date().toISOString(),
      briefings: {
        jira: $json.jira_briefing || null,
        calendar: $json.calendar_briefing || null,
        email: $json.email_briefing || null
      }
    }
  }
];

const payload = $json || {};
const userId = String(payload.user_id || '').trim();
const generatedAt = payload.generated_at || new Date().toISOString();
const briefings = payload.briefings && typeof payload.briefings === 'object' ? payload.briefings : {};
const allowedPriorities = new Set(['high', 'medium', 'low']);
const allowedStatuses = new Set(['success', 'partial', 'failed']);
const rows = [];

for (const domain of ['jira', 'calendar', 'email']) {
  const briefing = briefings[domain];
  if (!briefing || !userId) continue;

  rows.push({
    user_id: userId,
    domain,
    priority: allowedPriorities.has(briefing.priority) ? briefing.priority : 'medium',
    headline: String(briefing.headline || '').trim() || 'Briefing belum tersedia',
    summary_points: Array.isArray(briefing.summary_points) ? briefing.summary_points.slice(0, 4) : [],
    source_metrics: briefing.source_metrics && typeof briefing.source_metrics === 'object' ? briefing.source_metrics : {},
    generated_at: generatedAt,
    status: allowedStatuses.has(briefing.status) ? briefing.status : 'success',
    error_message: briefing.error_message ? String(briefing.error_message) : null,
  });
}

return [{
  json: {
    response_payload: payload,
    supabase_rows: rows,
  }
}];

const prepared = $('Prepare Supabase Upsert Rows').item.json || {};
return [{
  json: prepared.response_payload || {
    success: false,
    generated_at: new Date().toISOString(),
    briefings: {},
  }
}];
